import { useEffect, useMemo, useState } from 'react'
import type { ChangeEvent, FormEvent, ReactNode } from 'react'
import {
  Activity, AlertTriangle, BarChart3, BookOpen, BrainCircuit, Check, CheckCircle2,
  ChevronDown, CircleHelp, Clock3, Cpu, Database, Download, FileBarChart2, FileText,
  FolderKanban, Gauge, GitBranch, Layers3, LayoutDashboard, LockKeyhole, LogOut, Menu, Moon,
  Network, Plus, Search, Settings, ShieldCheck, Sparkles, Sun, Trash2, Upload,
  Users, Workflow, X, Zap, Pause, Play, RotateCcw, SlidersHorizontal
} from 'lucide-react'
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'

/* ============================================================================
   NEUROLAB ENTERPRISE — PROTOTIPO FUNCIONAL SIMULADO
   - La interfaz está construida con React + TypeScript.
   - Los datos de demostración se guardan en localStorage del navegador.
   - No se entrena una red neuronal real: los estados y las métricas son simulados.
   - Para producción, sustituir las funciones simuladas por llamadas a FastAPI.
   ============================================================================ */

type ModuleKey = 'dashboard' | 'datasets' | 'projects' | 'architectures' | 'training' | 'models' | 'evaluation' | 'reports' | 'fundamentals' | 'admin'
type Family = 'Feedforward' | 'RNN' | 'CNN' | 'GAN'
type Activation = 'Sigmoid' | 'ReLU' | 'Tanh' | 'Softmax' | 'Linear'
type Optimizer = 'Adam' | 'SGD' | 'RMSprop'
type LossName = 'binary_crossentropy' | 'categorical_crossentropy' | 'mse'
type Dataset = { id: string; name: string; rows: number; columns: number; size: string; uploadedAt: string; fields: string[] }
type Layer = { id: string; neurons: number; activation: Activation }
type Project = { id: string; name: string; description: string; datasetId: string; family: Family; status: 'Activo' | 'Borrador' | 'Inactivo'; createdAt: string; inputNeurons: number; outputNeurons: number; outputActivation: Activation; layers: Layer[]; optimizer: Optimizer; loss: LossName; epochs: number }
type Job = { id: string; projectId: string; projectName: string; family: Family; modelActive: boolean; status: 'En ejecución' | 'Completado' | 'Pausado' | 'Cancelado' | 'Incompleto'; epoch: number; epochs: number; loss: number; accuracy: number; elapsed: number; optimizer: Optimizer; lossFunction: LossName; history: { epoch: number; loss: number; accuracy: number }[]; createdAt: string }
type User = { name: string; email: string; role: string }

const STORAGE = 'neurolab_enterprise_sim_v2'
const nav: { key: ModuleKey; label: string; group: string; icon: typeof Gauge }[] = [
  { key: 'dashboard', label: 'Dashboard', group: 'ESPACIO DE TRABAJO', icon: LayoutDashboard },
  { key: 'projects', label: 'Proyectos de IA', group: 'ESPACIO DE TRABAJO', icon: FolderKanban },
  { key: 'datasets', label: 'Datasets', group: 'PREPARACIÓN DE DATOS', icon: Database },
  { key: 'architectures', label: 'Diseñador de redes', group: 'DISEÑO DEL MODELO', icon: Network },
  { key: 'training', label: 'Entrenamientos', group: 'EXPERIMENTACIÓN', icon: Zap },
  { key: 'evaluation', label: 'Evaluación y métricas', group: 'EXPERIMENTACIÓN', icon: BarChart3 },
  { key: 'models', label: 'Modelos creados', group: 'GESTIÓN DE MODELOS', icon: GitBranch },
  { key: 'reports', label: 'Reportes', group: 'GESTIÓN DE MODELOS', icon: FileBarChart2 },
  { key: 'fundamentals', label: 'Fundamentos neuronales', group: 'RECURSOS', icon: BookOpen },
  { key: 'admin', label: 'Administración', group: 'SISTEMA', icon: ShieldCheck },
]
const families: Family[] = ['Feedforward', 'RNN', 'CNN', 'GAN']
const activations: Activation[] = ['Sigmoid', 'ReLU', 'Tanh', 'Softmax', 'Linear']
const optimizers: Optimizer[] = ['Adam', 'SGD', 'RMSprop']
const losses: LossName[] = ['binary_crossentropy', 'categorical_crossentropy', 'mse']
const uid = () => Math.random().toString(36).slice(2, 10).toUpperCase()
const dateLabel = () => new Date().toLocaleString('es-PE', { dateStyle: 'short', timeStyle: 'short' })
const starterLayer = (): Layer[] => [{ id: uid(), neurons: 8, activation: 'ReLU' }, { id: uid(), neurons: 8, activation: 'ReLU' }]
const initialProject: Project = { id: 'PRJ-DEMO01', name: 'Clasificación de clientes', description: 'Proyecto de demostración para clasificar registros tabulares.', datasetId: 'DS-DEMO01', family: 'Feedforward', status: 'Activo', createdAt: dateLabel(), inputNeurons: 6, outputNeurons: 1, outputActivation: 'Sigmoid', layers: starterLayer(), optimizer: 'Adam', loss: 'binary_crossentropy', epochs: 30 }
const initialDataset: Dataset = { id: 'DS-DEMO01', name: 'clientes_demo.csv', rows: 1200, columns: 6, size: '84 KB', uploadedAt: dateLabel(), fields: ['edad', 'ingresos', 'antigüedad', 'compras', 'segmento', 'objetivo'] }
const initialState = { datasets: [initialDataset], projects: [initialProject], jobs: [] as Job[], theme: 'light' as 'light' | 'dark', user: null as User | null }

function loadState(): typeof initialState {
  try {
    const saved = localStorage.getItem(STORAGE)
    return saved ? { ...initialState, ...JSON.parse(saved) } : initialState
  } catch { return initialState }
}

export default function App() {
  // Estado principal: conserva datasets, proyectos, entrenamientos, usuario y tema.
  const [saved, setSaved] = useState(loadState)
  const [active, setActive] = useState<ModuleKey>('dashboard')
  const [loginEmail, setLoginEmail] = useState('admin@neurolab.local')
  const [loginPassword, setLoginPassword] = useState('NeuroLab2026!')
  const [loginError, setLoginError] = useState('')
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [search, setSearch] = useState('')
  const [toast, setToast] = useState('')
  const [projectModal, setProjectModal] = useState(false)
  const [projectName, setProjectName] = useState('')
  const [projectDescription, setProjectDescription] = useState('')
  const [projectDataset, setProjectDataset] = useState('')
  const [projectFamily, setProjectFamily] = useState<Family>('Feedforward')
  const [selectedProjectId, setSelectedProjectId] = useState(initialProject.id)
  const [layerDraft, setLayerDraft] = useState<Layer[]>(initialProject.layers)
  const [archFamily, setArchFamily] = useState<Family>('Feedforward')
  const [archOptimizer, setArchOptimizer] = useState<Optimizer>('Adam')
  const [archLoss, setArchLoss] = useState<LossName>('binary_crossentropy')
  const [archEpochs, setArchEpochs] = useState(30)
  const [inputNeurons, setInputNeurons] = useState(6)
  const [outputNeurons, setOutputNeurons] = useState(1)
  const [outputActivation, setOutputActivation] = useState<Activation>('Sigmoid')
  const [trainingProjectId, setTrainingProjectId] = useState(initialProject.id)
  const [trainingEpochs, setTrainingEpochs] = useState(30)
  const [filterJobs, setFilterJobs] = useState('Todos')

  // Guardar el estado del prototipo después de cada cambio para conservar la demo al recargar.
  useEffect(() => { localStorage.setItem(STORAGE, JSON.stringify(saved)) }, [saved])
  // El temporizador representa épocas de entrenamiento simuladas y actualiza pérdida, exactitud y tiempo.
  useEffect(() => {
    const timer = window.setInterval(() => {
      setSaved(old => {
        let changed = false
        const jobs = old.jobs.map(job => {
          if (job.status !== 'En ejecución') return job
          changed = true
          const nextEpoch = Math.min(job.epoch + 1, job.epochs)
          const nextLoss = Math.max(0.025, job.loss * (0.91 + Math.random() * 0.045))
          const nextAccuracy = Math.min(0.995, job.accuracy + Math.random() * 0.018 + 0.002)
          const history = [...job.history, { epoch: nextEpoch, loss: Number(nextLoss.toFixed(4)), accuracy: Number(nextAccuracy.toFixed(4)) }]
          return { ...job, epoch: nextEpoch, loss: Number(nextLoss.toFixed(4)), accuracy: Number(nextAccuracy.toFixed(4)), elapsed: job.elapsed + 1, history, status: nextEpoch >= job.epochs ? 'Completado' as const : job.status, modelActive: nextEpoch >= job.epochs ? true : job.modelActive }
        })
        return changed ? { ...old, jobs } : old
      })
    }, 900)
    return () => window.clearInterval(timer)
  }, [])
  // Mensaje temporal de confirmación para acciones comunes.
  useEffect(() => { if (!toast) return; const t = window.setTimeout(() => setToast(''), 3200); return () => window.clearTimeout(t) }, [toast])

  const projects = saved.projects as Project[]
  const datasets = saved.datasets as Dataset[]
  const jobs = saved.jobs as Job[]
  const selectedProject = projects.find(p => p.id === selectedProjectId) || projects[0]
  const selectedTrainingProject = projects.find(p => p.id === trainingProjectId) || projects[0]
  const activeJobs = jobs.filter(j => j.status === 'En ejecución').length
  const completedJobs = jobs.filter(j => j.status === 'Completado').length
  const activeModels = jobs.filter(j => j.status === 'Completado' && j.modelActive).length
  const activeProjects = projects.filter(p => p.status === 'Activo').length
  const visibleNav = useMemo(() => nav.filter(n => n.label.toLowerCase().includes(search.toLowerCase())), [search])

  const login = (e: FormEvent) => {
    e.preventDefault()
    if (loginEmail.trim().toLowerCase() === 'admin@neurolab.local' && loginPassword === 'NeuroLab2026!') {
      setSaved(old => ({ ...old, user: { name: 'Administrador NeuroLab', email: loginEmail.trim(), role: 'Administrador' } }))
      setLoginError('')
    } else setLoginError('Credenciales de demostración incorrectas. Revisa el correo y la contraseña.')
  }
  const logout = () => { setSaved(old => ({ ...old, user: null })); setActive('dashboard') }
  const go = (key: ModuleKey) => { setActive(key); setSidebarOpen(false) }
  const updateSaved = (partial: Partial<typeof initialState>) => setSaved(old => ({ ...old, ...partial }))

  // Recibe CSV local y simula un diagnóstico de filas/columnas para la demostración.
  const uploadDataset = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return
    if (!file.name.toLowerCase().endsWith('.csv')) { setToast('Selecciona un archivo con extensión .csv'); return }
    const text = await file.text()
    const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0)
    const fields = (lines[0] || '').split(',').map(x => x.trim().replace(/^"|"$/g, '')).filter(Boolean)
    const dataset: Dataset = { id: `DS-${uid()}`, name: file.name, rows: Math.max(0, lines.length - 1), columns: fields.length, size: file.size < 1024 * 1024 ? `${Math.max(1, Math.round(file.size / 1024))} KB` : `${(file.size / 1024 / 1024).toFixed(2)} MB`, uploadedAt: dateLabel(), fields }
    updateSaved({ datasets: [dataset, ...datasets] })
    setProjectDataset(dataset.id)
    setToast(`Dataset ${file.name} agregado a la biblioteca de demostración.`)
    event.target.value = ''
  }
  const createProject = (e: FormEvent) => {
    e.preventDefault()
    if (!projectName.trim() || !projectDataset) { setToast('Escribe un nombre y selecciona un dataset.'); return }
    const project: Project = { id: `PRJ-${uid()}`, name: projectName.trim(), description: projectDescription.trim(), datasetId: projectDataset, family: projectFamily, status: 'Activo', createdAt: dateLabel(), inputNeurons: 6, outputNeurons: 1, outputActivation: 'Sigmoid', layers: starterLayer(), optimizer: 'Adam', loss: 'binary_crossentropy', epochs: 30 }
    updateSaved({ projects: [project, ...projects] })
    setSelectedProjectId(project.id); setTrainingProjectId(project.id); setProjectModal(false); setProjectName(''); setProjectDescription(''); setToast('Proyecto creado y vinculado al dataset seleccionado.')
  }
  const loadArchitecture = (id: string) => {
    setSelectedProjectId(id)
    const project = projects.find(p => p.id === id)
    if (project) { setLayerDraft(project.layers.map(l => ({ ...l }))); setArchFamily(project.family); setInputNeurons(project.inputNeurons || 6); setOutputNeurons(project.outputNeurons || 1); setOutputActivation(project.outputActivation || 'Sigmoid'); setArchOptimizer(project.optimizer); setArchLoss(project.loss); setArchEpochs(project.epochs) }
  }
  const saveArchitecture = () => {
    if (!selectedProject) { setToast('Primero crea un proyecto.'); return }
    if (layerDraft.some(l => l.neurons < 1 || l.neurons > 4096)) { setToast('Cada capa debe tener entre 1 y 4096 neuronas.'); return }
    const updated = projects.map(p => p.id === selectedProject.id ? { ...p, family: archFamily, inputNeurons, outputNeurons, outputActivation, layers: layerDraft, optimizer: archOptimizer, loss: archLoss, epochs: archEpochs } : p)
    updateSaved({ projects: updated }); setToast('Arquitectura validada y guardada en la simulación.')
  }
  const addLayer = () => setLayerDraft(old => [...old, { id: uid(), neurons: 8, activation: 'ReLU' }])
  const removeLayer = (id: string) => setLayerDraft(old => old.filter(layer => layer.id !== id))
  const updateLayer = (id: string, key: 'neurons' | 'activation', value: number | Activation) => setLayerDraft(old => old.map(layer => layer.id === id ? { ...layer, [key]: value } : layer))
  const startTraining = () => {
    if (!selectedTrainingProject) { setToast('Crea un proyecto antes de iniciar el entrenamiento.'); return }
    const dataset = datasets.find(d => d.id === selectedTrainingProject.datasetId)
    if (!dataset) { setToast('El proyecto necesita un dataset válido.'); return }
    const job: Job = { id: `TRN-${uid()}`, projectId: selectedTrainingProject.id, projectName: selectedTrainingProject.name, family: selectedTrainingProject.family, modelActive: false, status: 'En ejecución', epoch: 0, epochs: trainingEpochs, loss: 1.2, accuracy: 0.5, elapsed: 0, optimizer: selectedTrainingProject.optimizer, lossFunction: selectedTrainingProject.loss, history: [], createdAt: dateLabel() }
    updateSaved({ jobs: [job, ...jobs] }); go('training'); setToast('Entrenamiento simulado iniciado. Las métricas se actualizarán automáticamente.')
  }
  const updateJobStatus = (id: string, status: Job['status']) => { updateSaved({ jobs: jobs.map(job => job.id === id ? { ...job, status } : job) }); setToast(status === 'Pausado' ? 'Entrenamiento pausado.' : status === 'Cancelado' ? 'Entrenamiento desactivado.' : 'Estado del entrenamiento actualizado.') }
  const deleteJob = (id: string) => { updateSaved({ jobs: jobs.filter(job => job.id !== id) }); setToast('Entrenamiento eliminado de la simulación.') }
  const deleteProject = (id: string) => { updateSaved({ projects: projects.filter(p => p.id !== id), jobs: jobs.filter(j => j.projectId !== id) }); if (selectedProjectId === id) setSelectedProjectId(projects.find(p => p.id !== id)?.id || ''); setToast('Proyecto y sus entrenamientos asociados eliminados.') }
  const toggleProject = (id: string) => updateSaved({ projects: projects.map(p => p.id === id ? { ...p, status: p.status === 'Activo' ? 'Inactivo' : 'Activo' } : p) })
  const exportJobs = () => {
    const rows = [['id','proyecto','familia','estado','epoca_actual','epocas_totales','perdida','precision','tiempo_segundos','optimizador','funcion_perdida'], ...jobs.map(j => [j.id,j.projectName,j.family,j.status,j.epoch,j.epochs,j.loss,j.accuracy,j.elapsed,j.optimizer,j.lossFunction])]
    const csv = rows.map(row => row.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\r\n')
    const url = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' }))
    const a = document.createElement('a'); a.href = url; a.download = 'neurolab_entrenamientos.csv'; a.click(); URL.revokeObjectURL(url)
  }
  const resetDemo = () => { if (window.confirm('¿Restablecer todos los datos de demostración?')) { setSaved(initialState); setSelectedProjectId(initialProject.id); setTrainingProjectId(initialProject.id); setToast('Datos de demostración restablecidos.') } }

  if (!saved.user) return <Login email={loginEmail} setEmail={setLoginEmail} password={loginPassword} setPassword={setLoginPassword} onSubmit={login} error={loginError} />
  const title = nav.find(n => n.key === active)?.label || 'Dashboard'

  return <div className={`app-shell theme-${saved.theme}`}>
    {sidebarOpen && <button aria-label="Cerrar menú" className="mobile-scrim" onClick={() => setSidebarOpen(false)} />}
    <aside className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><BrainCircuit size={25}/></div><div className="brand-copy"><strong>NeuroLab <span>Enterprise</span></strong><small>NEURAL NETWORK STUDIO</small></div><button className="icon-btn mobile-only" onClick={() => setSidebarOpen(false)} aria-label="Cerrar menú"><X size={18}/></button></div>
      <div className="workspace-card"><div className="workspace-avatar">NL</div><div><b>Laboratorio IA</b><small>Workspace principal</small></div><ChevronDown size={15}/></div>
      <div className="nav-search"><Search size={15}/><input placeholder="Buscar módulo..." value={search} onChange={e => setSearch(e.target.value)}/><kbd>⌘ K</kbd></div>
      <nav className="side-nav">{visibleNav.map((item, index) => <div key={item.key}>{(index === 0 || item.group !== visibleNav[index - 1]?.group) && <div className="nav-group-label">{item.group}</div>}<button className={`nav-item ${active === item.key ? 'active' : ''}`} onClick={() => go(item.key)}><item.icon size={18}/><span>{item.label}</span>{item.key === 'training' && activeJobs > 0 && <em>{activeJobs}</em>}</button></div>)}</nav>
      <div className="sidebar-bottom"><div className="usage-card"><div className="usage-top"><span>Uso del laboratorio</span><b>{Math.min(100, 20 + projects.length * 8)}%</b></div><div className="usage-track"><span style={{ width: `${Math.min(100, 20 + projects.length * 8)}%` }}/></div><small>Entorno de simulación académica</small></div><button className="nav-item" onClick={() => go('admin')}><Settings size={18}/><span>Configuración</span></button><div className="user-mini"><div className="user-avatar">AD</div><div className="user-copy"><b>{saved.user.name}</b><small>{saved.user.role}</small></div><button className="icon-btn" title="Cerrar sesión" onClick={logout}><LogOut size={17}/></button></div></div>
    </aside>

    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="icon-btn mobile-only" onClick={() => setSidebarOpen(true)} aria-label="Abrir menú"><Menu size={20}/></button><div className="breadcrumbs"><span>NeuroLab</span><span>/</span><b>{title}</b></div></div><div className="topbar-actions"><span className="demo-indicator"><i/> Modo simulación</span><button className="icon-btn theme-toggle" title="Cambiar tema" onClick={() => updateSaved({ theme: saved.theme === 'light' ? 'dark' : 'light' })}>{saved.theme === 'light' ? <Moon size={18}/> : <Sun size={18}/>}</button><button className="top-avatar" title={saved.user.email}>{saved.user.name.split(' ').map(s => s[0]).slice(0,2).join('')}</button></div></header>
      <div className="page-content">
        {active === 'dashboard' && <Dashboard projects={projects} datasets={datasets} jobs={jobs} activeProjects={activeProjects} activeJobs={activeJobs} completedJobs={completedJobs} activeModels={activeModels} stopJob={id => updateJobStatus(id, 'Cancelado')} go={go} create={() => { setProjectDataset(datasets[0]?.id || ''); setProjectModal(true) }} />}
        {active === 'datasets' && <Datasets datasets={datasets} uploadDataset={uploadDataset} go={go} />}
        {active === 'projects' && <Projects projects={projects} datasets={datasets} create={() => { setProjectDataset(datasets[0]?.id || ''); setProjectModal(true) }} toggle={toggleProject} remove={deleteProject} editArchitecture={id => { loadArchitecture(id); go('architectures') }} />}
        {active === 'architectures' && <Architecture projects={projects} datasets={datasets} selectedProject={selectedProject} selectedProjectId={selectedProjectId} loadArchitecture={loadArchitecture} family={archFamily} setFamily={setArchFamily} layers={layerDraft} addLayer={addLayer} removeLayer={removeLayer} updateLayer={updateLayer} inputNeurons={inputNeurons} setInputNeurons={setInputNeurons} outputNeurons={outputNeurons} setOutputNeurons={setOutputNeurons} outputActivation={outputActivation} setOutputActivation={setOutputActivation} optimizer={archOptimizer} setOptimizer={setArchOptimizer} loss={archLoss} setLoss={setArchLoss} epochs={archEpochs} setEpochs={setArchEpochs} save={saveArchitecture} />}
        {active === 'training' && <Training jobs={jobs} projects={projects} selectedProjectId={trainingProjectId} setSelectedProjectId={setTrainingProjectId} epochs={trainingEpochs} setEpochs={setTrainingEpochs} start={startTraining} updateStatus={updateJobStatus} remove={deleteJob} exportJobs={exportJobs} filter={filterJobs} setFilter={setFilterJobs} />}
        {active === 'models' && <Models jobs={jobs} projects={projects} go={go} toggleModel={id => updateSaved({ jobs: jobs.map(j => j.id === id ? { ...j, modelActive: !j.modelActive } : j) })} />}
        {active === 'evaluation' && <Evaluation jobs={jobs} />}
        {active === 'reports' && <Reports projects={projects} datasets={datasets} jobs={jobs} exportJobs={exportJobs} />}
        {active === 'fundamentals' && <Fundamentals />}
        {active === 'admin' && <Admin user={saved.user} theme={saved.theme} reset={resetDemo} />}
      </div>
      <footer className="app-footer"><span>© 2026 NeuroLab Enterprise</span><span><i/> Todos los datos y entrenamientos de esta versión son simulados</span><span>v2.0.0 · Responsive</span></footer>
    </main>
    {projectModal && <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setProjectModal(false) }}><form className="modal-card" onSubmit={createProject}><div className="modal-head"><div><span className="eyebrow">NUEVO EXPERIMENTO</span><h2>Crear proyecto de IA</h2><p>Selecciona primero un dataset para asociarlo al proyecto.</p></div><button type="button" className="icon-btn" onClick={() => setProjectModal(false)}><X size={18}/></button></div><label>Nombre del proyecto<input autoFocus required value={projectName} onChange={e => setProjectName(e.target.value)} placeholder="Ej. Predicción de ventas"/></label><label>Descripción<textarea value={projectDescription} onChange={e => setProjectDescription(e.target.value)} placeholder="Describe el objetivo del modelo..." rows={3}/></label><label>Dataset de origen<select required value={projectDataset} onChange={e => setProjectDataset(e.target.value)}><option value="">Selecciona un dataset...</option>{datasets.map(d => <option key={d.id} value={d.id}>{d.name} · {d.rows.toLocaleString()} filas</option>)}</select></label><label>Familia de red neuronal<select value={projectFamily} onChange={e => setProjectFamily(e.target.value as Family)}>{families.map(f => <option key={f}>{f}</option>)}</select></label><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={() => setProjectModal(false)}>Cancelar</button><button className="btn btn-primary" type="submit"><Plus size={16}/> Crear proyecto</button></div></form></div>}
    {toast && <div className="toast"><CheckCircle2 size={18}/>{toast}<button onClick={() => setToast('')}><X size={15}/></button></div>}
  </div>
}

function Login(p: { email: string; setEmail: (v: string) => void; password: string; setPassword: (v: string) => void; onSubmit: (e: FormEvent) => void; error: string }) {
  const [showPassword, setShowPassword] = useState(false)
  return <div className="login-page"><div className="login-art"><div className="login-art-glow glow-one"/><div className="login-art-glow glow-two"/><div className="login-brand"><div className="brand-mark"><BrainCircuit size={27}/></div><div><strong>NeuroLab <span>Enterprise</span></strong><small>NEURAL NETWORK STUDIO</small></div></div><div className="login-hero"><span className="hero-chip"><Sparkles size={14}/> PLATAFORMA DE IA · DEMO</span><h1>Diseña. Entrena.<br/><em>Descubre.</em></h1><p>Un espacio de trabajo para crear arquitecturas neuronales, explorar datasets y monitorizar experimentos de inteligencia artificial.</p><div className="network-art"><div className="network-lines"/><div className="network-col"><i/><i/><i/><i/></div><div className="network-col middle"><i/><i/><i/><i/><i/></div><div className="network-col"><i/><i/><i/></div></div><div className="login-stat-row"><div><b>04</b><span>Familias de redes</span></div><div><b>10</b><span>Módulos integrados</span></div><div><b>100%</b><span>Responsive</span></div></div></div><div className="login-art-footer"><span>© 2026 NeuroLab Enterprise</span><span>Entorno académico simulado</span></div></div><div className="login-panel"><div className="login-panel-inner"><div className="login-mobile-brand"><div className="brand-mark"><BrainCircuit size={24}/></div><b>NeuroLab Enterprise</b></div><span className="eyebrow">BIENVENIDO DE NUEVO</span><h2>Accede a tu laboratorio</h2><p className="login-subtitle">Ingresa tus credenciales para continuar con tus experimentos.</p><form className="login-form" onSubmit={p.onSubmit}><label>Correo electrónico<div className="input-with-icon"><Users size={17}/><input type="email" required value={p.email} onChange={e => p.setEmail(e.target.value)} placeholder="nombre@empresa.com"/></div></label><label>Contraseña<div className="input-with-icon"><ShieldCheck size={17}/><input type={showPassword ? 'text' : 'password'} required value={p.password} onChange={e => p.setPassword(e.target.value)} placeholder="Tu contraseña"/><button type="button" className="show-password" onClick={() => setShowPassword(!showPassword)}>{showPassword ? 'Ocultar' : 'Ver'}</button></div></label>{p.error && <div className="login-error"><AlertTriangle size={16}/>{p.error}</div>}<button className="btn btn-primary login-submit" type="submit">Entrar al laboratorio <span>→</span></button></form><div className="demo-credentials"><div className="demo-credential-icon"><ShieldCheck size={19}/></div><div><b>Acceso de demostración</b><p>admin@neurolab.local</p><p>NeuroLab2026!</p></div><button className="text-button" onClick={() => { p.setEmail('admin@neurolab.local'); p.setPassword('NeuroLab2026!') }}>Usar demo</button></div><div className="login-security"><LockKeyhole size={14}/> Acceso local de prueba. No usar credenciales reales.</div></div></div></div>
}

function PageIntro(p: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="page-intro"><div><span className="eyebrow">{p.eyebrow}</span><h1>{p.title}</h1><p>{p.description}</p></div>{p.action && <div className="intro-actions">{p.action}</div>}</div> }
function Metric(p: { label: string; value: string | number; note: string; icon: typeof Gauge; color: string; trend?: string }) { const I = p.icon; return <div className={`metric-card metric-${p.color}`}><div className="metric-top"><span>{p.label}</span><div className="metric-icon"><I size={19}/></div></div><div className="metric-value">{p.value}</div><div className="metric-bottom"><span>{p.note}</span>{p.trend && <b>{p.trend}</b>}</div></div> }
function Empty(p: { icon: typeof Database; title: string; text: string; action?: ReactNode }) { const I = p.icon; return <div className="empty-state"><div><I size={25}/></div><h3>{p.title}</h3><p>{p.text}</p>{p.action}</div> }
function Status(p: { value: string }) { const kind = p.value === 'Activo' || p.value === 'Completado' ? 'status-green' : p.value === 'En ejecución' ? 'status-blue' : p.value === 'Pausado' ? 'status-amber' : 'status-gray'; return <span className={`status-pill ${kind}`}><i/>{p.value}</span> }

function Dashboard(p: { projects: Project[]; datasets: Dataset[]; jobs: Job[]; activeProjects: number; activeJobs: number; completedJobs: number; activeModels: number; stopJob: (id: string) => void; go: (k: ModuleKey) => void; create: () => void }) {
  const latest = p.jobs.slice(0, 5)
  const chart = [...p.jobs].reverse().flatMap(job => job.history.slice(-4).map(point => ({ name: `${job.id.slice(-4)} · ${point.epoch}`, loss: point.loss, accuracy: point.accuracy * 100 }))).slice(-16)
  return <><PageIntro eyebrow="OVERVIEW / WORKSPACE" title="Tu laboratorio, en perspectiva." description="Supervisa proyectos, prepara datos y controla tus experimentos neuronales desde un solo lugar." action={<><button className="btn btn-secondary" onClick={() => p.go('datasets')}><Upload size={16}/> Cargar dataset</button><button className="btn btn-primary" onClick={p.create}><Plus size={17}/> Nuevo proyecto</button></>}/><div className="welcome-banner"><div className="welcome-copy"><span><Sparkles size={15}/> LABORATORIO DE INTELIGENCIA ARTIFICIAL</span><h2>Convierte tus datos en experimentos.</h2><p>Comienza por cargar un CSV, crea un proyecto y configura la arquitectura de tu red neuronal.</p><button className="banner-link" onClick={() => p.go('architectures')}>Explorar diseñador de redes <span>→</span></button></div><div className="welcome-graphic"><div className="orbit orbit-a"/><div className="orbit orbit-b"/><div className="orbit orbit-c"/><div className="orbit-core"><BrainCircuit size={35}/></div><i className="orbit-dot dot-a"/><i className="orbit-dot dot-b"/><i className="orbit-dot dot-c"/></div></div><div className="metric-grid"><Metric label="Proyectos creados" value={p.projects.length.toString().padStart(2,'0')} note={`${p.activeProjects} activos`} icon={FolderKanban} color="purple" trend="Workspace"/><Metric label="Datasets disponibles" value={p.datasets.length.toString().padStart(2,'0')} note="Archivos de datos" icon={Database} color="blue" trend="Biblioteca"/><Metric label="Entrenamientos activos" value={p.activeJobs.toString().padStart(2,'0')} note="En progreso simulado" icon={Activity} color="green" trend={p.activeJobs ? 'En vivo' : 'En espera'}/><Metric label="Modelos creados" value={p.completedJobs.toString().padStart(2,'0')} note="Ejecuciones terminadas" icon={BrainCircuit} color="orange" trend="Registro"/><Metric label="Modelos activos" value={p.activeModels.toString().padStart(2,'0')} note="Disponibles en la demo" icon={CheckCircle2} color="green" trend="Operativos"/></div><div className="dashboard-grid"><section className="panel performance-panel"><div className="panel-heading"><div><span className="eyebrow">RENDIMIENTO</span><h3>Actividad de entrenamiento</h3><p>Curvas de pérdida generadas por las simulaciones.</p></div><button className="link-button" onClick={() => p.go('evaluation')}>Ver métricas <span>→</span></button></div>{chart.length ? <div className="chart-box"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart}><defs><linearGradient id="lossFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7657f6" stopOpacity={0.24}/><stop offset="95%" stopColor="#7657f6" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid strokeDasharray="4 4" vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="name" tick={{ fontSize: 10 }} tickLine={false} axisLine={false}/><YAxis tick={{ fontSize: 10 }} tickLine={false} axisLine={false}/><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid var(--border)', background: 'var(--panel)' }}/><Area type="monotone" dataKey="loss" name="Pérdida" stroke="#7657f6" fill="url(#lossFill)" strokeWidth={2.5}/><Area type="monotone" dataKey="accuracy" name="Precisión (%)" stroke="#13b98b" fill="#13b98b10" strokeWidth={2}/></AreaChart></ResponsiveContainer></div> : <Empty icon={Activity} title="Todavía no hay actividad" text="Inicia un entrenamiento para visualizar las curvas de rendimiento." action={<button className="btn btn-primary" onClick={() => p.go('training')}>Ir a entrenamientos</button>}/>}</section><section className="panel quick-panel"><div className="panel-heading"><div><span className="eyebrow">ACCESOS RÁPIDOS</span><h3>¿Qué deseas hacer?</h3><p>Continúa con el siguiente paso de tu flujo.</p></div></div><div className="quick-actions"><button onClick={() => p.go('datasets')}><div className="quick-icon violet"><Upload size={19}/></div><span><b>Cargar dataset</b><small>Importa un archivo CSV</small></span><span className="quick-arrow">→</span></button><button onClick={p.create}><div className="quick-icon blue"><FolderKanban size={19}/></div><span><b>Crear proyecto</b><small>Asocia datos y familia de red</small></span><span className="quick-arrow">→</span></button><button onClick={() => p.go('architectures')}><div className="quick-icon green"><Workflow size={19}/></div><span><b>Diseñar arquitectura</b><small>Personaliza capas y parámetros</small></span><span className="quick-arrow">→</span></button><button onClick={() => p.go('training')}><div className="quick-icon orange"><Zap size={19}/></div><span><b>Entrenar modelo</b><small>Monitorea épocas y métricas</small></span><span className="quick-arrow">→</span></button></div></section></div><section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">RECIENTES</span><h3>Proyectos de IA</h3><p>Estado y dataset asociado a cada proyecto.</p></div><button className="link-button" onClick={() => p.go('projects')}>Ver proyectos <span>→</span></button></div>{p.projects.length ? <div className="table-scroll"><table><thead><tr><th>Proyecto</th><th>Familia</th><th>Dataset</th><th>Creado</th><th>Estado</th></tr></thead><tbody>{p.projects.slice(0,5).map(project => <tr key={project.id}><td><div className="table-primary"><div className="table-project-icon"><BrainCircuit size={17}/></div><span><b>{project.name}</b><small>{project.id}</small></span></div></td><td><span className="family-tag">{project.family}</span></td><td>{p.datasets.find(d => d.id === project.datasetId)?.name || 'Sin dataset'}</td><td>{project.createdAt}</td><td><Status value={project.status}/></td></tr>)}</tbody></table></div> : <Empty icon={FolderKanban} title="Crea tu primer proyecto" text="Los proyectos aparecerán aquí una vez que asocies un dataset."/>}</section><section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">LIVE EXPERIMENTS</span><h3>Entrenamientos activos</h3><p>Desactiva directamente desde el dashboard una simulación en curso.</p></div><button className="link-button" onClick={() => p.go('training')}>Administrar todos <span>→</span></button></div>{p.jobs.filter(job => job.status === 'En ejecución').length ? <div className="table-scroll"><table><thead><tr><th>Proyecto</th><th>Progreso</th><th>Pérdida</th><th>Precisión</th><th>Tiempo</th><th>Acción</th></tr></thead><tbody>{p.jobs.filter(job => job.status === 'En ejecución').map(job => <tr key={job.id}><td><div className="table-primary"><div className="table-project-icon"><Activity size={16}/></div><span><b>{job.projectName}</b><small>{job.id}</small></span></div></td><td>{job.epoch}/{job.epochs}<div className="mini-progress"><i style={{width:`${job.epoch / job.epochs * 100}%`}}/></div></td><td>{job.loss.toFixed(4)}</td><td>{(job.accuracy * 100).toFixed(2)}%</td><td>{job.elapsed}s</td><td><button className="btn btn-danger btn-small" onClick={() => p.stopJob(job.id)}><X size={13}/> Desactivar</button></td></tr>)}</tbody></table></div> : <Empty icon={Activity} title="No hay entrenamientos activos" text="Cuando inicies una simulación, podrás ver su progreso y desactivarla aquí." action={<button className="btn btn-primary" onClick={() => p.go('training')}>Iniciar entrenamiento</button>}/>}</section></>
}

function Datasets(p: { datasets: Dataset[]; uploadDataset: (e: ChangeEvent<HTMLInputElement>) => void; go: (k: ModuleKey) => void }) { return <><PageIntro eyebrow="DATA MANAGEMENT" title="Biblioteca de datasets" description="Carga archivos CSV, consulta sus metadatos y utiliza los datos como punto de partida de un proyecto." action={<label className="btn btn-primary file-button"><Upload size={16}/> Cargar CSV<input type="file" accept=".csv,text/csv" onChange={p.uploadDataset}/></label>}/><div className="upload-zone"><div className="upload-symbol"><Upload size={25}/></div><h3>Importa un dataset para comenzar</h3><p>Formato CSV · La demo lee el encabezado y cuenta filas localmente. No sube datos a un servidor.</p><label className="btn btn-secondary file-button">Seleccionar archivo<input type="file" accept=".csv,text/csv" onChange={p.uploadDataset}/></label><span className="upload-hint"><ShieldCheck size={14}/> Los datos se mantienen en tu navegador; se guardan solo los metadatos en esta simulación.</span></div><div className="section-title-row"><div><h2>Datasets registrados</h2><p>{p.datasets.length} archivos en tu biblioteca</p></div><span className="subtle-badge"><Database size={14}/> CSV / TABULAR</span></div><div className="dataset-grid">{p.datasets.map(ds => <article className="dataset-card" key={ds.id}><div className="dataset-card-top"><div className="dataset-icon"><FileText size={22}/></div><span className="file-extension">.CSV</span></div><h3>{ds.name}</h3><p>{ds.id} · Añadido {ds.uploadedAt}</p><div className="dataset-stats"><div><b>{ds.rows.toLocaleString()}</b><span>Filas</span></div><div><b>{ds.columns}</b><span>Columnas</span></div><div><b>{ds.size}</b><span>Tamaño</span></div></div><div className="field-chips">{ds.fields.slice(0,5).map(field => <span key={field}>{field}</span>)}{ds.fields.length > 5 && <span>+{ds.fields.length - 5}</span>}</div><div className="dataset-card-footer"><span><CheckCircle2 size={14}/> Disponible</span><button className="inline-action" onClick={() => p.go('projects')}>Crear proyecto <span>→</span></button></div></article>)}</div></> }

function Projects(p: { projects: Project[]; datasets: Dataset[]; create: () => void; toggle: (id: string) => void; remove: (id: string) => void; editArchitecture: (id: string) => void }) { return <><PageIntro eyebrow="PROJECT MANAGEMENT" title="Proyectos de IA" description="Cada proyecto vincula un dataset, una familia neuronal y una configuración de entrenamiento." action={<button className="btn btn-primary" onClick={p.create}><Plus size={17}/> Crear proyecto</button>}/><div className="project-grid">{p.projects.map(project => { const ds = p.datasets.find(d => d.id === project.datasetId); return <article className="project-card" key={project.id}><div className="project-card-top"><div className="project-logo"><BrainCircuit size={22}/></div><Status value={project.status}/><button className="icon-btn danger-hover" title="Eliminar proyecto" onClick={() => { if (window.confirm(`¿Eliminar el proyecto ${project.name} y sus entrenamientos?`)) p.remove(project.id) }}><Trash2 size={16}/></button></div><span className="project-id">{project.id}</span><h3>{project.name}</h3><p>{project.description || 'Sin descripción adicional.'}</p><div className="project-meta"><div><Database size={15}/><span>{ds?.name || 'Dataset no encontrado'}</span></div><div><Network size={15}/><span>{project.family}</span></div><div><Layers3 size={15}/><span>{project.layers.length} capas ocultas</span></div></div><div className="project-card-footer"><button className="btn btn-secondary btn-small" onClick={() => p.editArchitecture(project.id)}><SlidersHorizontal size={15}/> Configurar red</button><button className="btn btn-ghost btn-small" onClick={() => p.toggle(project.id)}>{project.status === 'Activo' ? 'Desactivar' : 'Activar'}</button></div></article> })}</div>{!p.projects.length && <Empty icon={FolderKanban} title="No hay proyectos" text="Carga un dataset y crea un proyecto para continuar."/>}</> }

function Architecture(p: { projects: Project[]; datasets: Dataset[]; selectedProject?: Project; selectedProjectId: string; loadArchitecture: (id: string) => void; family: Family; setFamily: (v: Family) => void; layers: Layer[]; addLayer: () => void; removeLayer: (id: string) => void; updateLayer: (id: string, key: 'neurons' | 'activation', value: number | Activation) => void; inputNeurons: number; setInputNeurons: (v: number) => void; outputNeurons: number; setOutputNeurons: (v: number) => void; outputActivation: Activation; setOutputActivation: (v: Activation) => void; optimizer: Optimizer; setOptimizer: (v: Optimizer) => void; loss: LossName; setLoss: (v: LossName) => void; epochs: number; setEpochs: (v: number) => void; save: () => void }) { const layers = p.layers; return <><PageIntro eyebrow="NEURAL ARCHITECTURE BUILDER" title="Diseñador de redes" description="Selecciona un proyecto y define las capas ocultas, neuronas, activaciones y parámetros de entrenamiento." action={<button className="btn btn-primary" onClick={p.save}><Check size={16}/> Validar y guardar</button>}/><div className="builder-toolbar panel"><label>Proyecto seleccionado<select value={p.selectedProjectId} onChange={e => p.loadArchitecture(e.target.value)}>{p.projects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Familia de red<select value={p.family} onChange={e => p.setFamily(e.target.value as Family)}>{families.map(f => <option key={f}>{f}</option>)}</select></label><div className="dataset-summary"><Database size={16}/><span><small>Dataset vinculado</small><b>{p.datasets.find(d => d.id === p.selectedProject?.datasetId)?.name || 'Sin dataset'}</b></span></div></div><div className="architecture-layout"><section className="panel architecture-canvas"><div className="panel-heading"><div><span className="eyebrow">VISUAL BUILDER</span><h3>Topología de la red</h3><p>Vista previa conceptual de entrada, capas ocultas y salida.</p></div><span className="subtle-badge"><Network size={14}/>{p.family}</span></div><div className="network-builder"><div className="network-layer"><span>Entrada</span>{Array.from({ length: Math.min(6, p.inputNeurons) }).map((_, i) => <i className="node input-node" key={i}/>)}<b>{p.inputNeurons} neuronas</b></div>{layers.map((layer, index) => <div className="network-layer" key={layer.id}><span>Capa oculta {index + 1}</span>{Array.from({ length: Math.min(8, layer.neurons) }).map((_, i) => <i className="node hidden-node" key={i}/>)}<b>{layer.neurons} neuronas</b></div>)}<div className="network-layer"><span>Salida</span>{Array.from({ length: Math.min(6, p.outputNeurons) }).map((_, i) => <i className="node output-node" key={i}/>)}<b>{p.outputNeurons} neurona(s)</b></div></div><div className="network-summary"><div><span>Capas ocultas</span><b>{layers.length}</b></div><div><span>Neuronas ocultas</span><b>{layers.reduce((n, l) => n + l.neurons, 0)}</b></div><div><span>Parámetros</span><b>~{layers.reduce((n,l) => n + l.neurons, p.inputNeurons + p.outputNeurons) * 4}</b></div></div></section><section className="panel layer-config"><div className="panel-heading"><div><span className="eyebrow">LAYER CONFIGURATION</span><h3>Configuración de capas</h3><p>Agrega o elimina capas ocultas según tu diseño.</p></div><button className="icon-btn accent-icon" title="Agregar capa" onClick={p.addLayer}><Plus size={19}/></button></div><div className="fixed-layer"><div className="fixed-layer-symbol">I</div><div><b>Capa de entrada</b><small>Representa las columnas de entrada del dataset.</small></div><label>Neuronas<input type="number" min="1" max="4096" value={p.inputNeurons} onChange={e => p.setInputNeurons(Math.max(1, Number(e.target.value)))}/></label></div>{layers.map((layer, index) => <div className="editable-layer" key={layer.id}><div className="layer-number">{String(index + 1).padStart(2,'0')}</div><div className="layer-fields"><b>Capa oculta {index + 1}</b><div className="layer-inputs"><label>Neuronas<input type="number" min="1" max="4096" value={layer.neurons} onChange={e => p.updateLayer(layer.id, 'neurons', Math.max(1, Number(e.target.value)))}/></label><label>Activación<select value={layer.activation} onChange={e => p.updateLayer(layer.id, 'activation', e.target.value as Activation)}>{activations.map(a => <option key={a}>{a}</option>)}</select></label></div></div><button className="icon-btn danger-hover" title="Eliminar capa" onClick={() => p.removeLayer(layer.id)}><Trash2 size={16}/></button></div>)}<button className="add-layer-button" onClick={p.addLayer}><Plus size={16}/> Añadir capa oculta</button><div className="fixed-layer output-fixed"><div className="fixed-layer-symbol">O</div><div><b>Capa de salida</b><small>Una neurona por defecto; se puede ajustar para la tarea.</small></div><label>Neuronas<input type="number" min="1" max="4096" value={p.outputNeurons} onChange={e => p.setOutputNeurons(Math.max(1, Number(e.target.value)))}/></label></div><div className="output-activation-row"><label>Activación de salida<select value={p.outputActivation} onChange={e => p.setOutputActivation(e.target.value as Activation)}>{activations.map(a => <option key={a}>{a}</option>)}</select></label></div></section></div><section className="panel training-settings"><div className="panel-heading"><div><span className="eyebrow">TRAINING HYPERPARAMETERS</span><h3>Parámetros del entrenamiento</h3><p>Los valores se guardan en el proyecto para utilizarlos en la simulación.</p></div><Settings size={20} className="muted-icon"/></div><div className="settings-grid"><label>Optimizador<select value={p.optimizer} onChange={e => p.setOptimizer(e.target.value as Optimizer)}>{optimizers.map(o => <option key={o}>{o}</option>)}</select><small>Algoritmo para actualizar los pesos.</small></label><label>Función de pérdida<select value={p.loss} onChange={e => p.setLoss(e.target.value as LossName)}>{losses.map(l => <option key={l}>{l}</option>)}</select><small>Mide el error entre predicción y objetivo.</small></label><label>Épocas máximas<input type="number" min="1" max="500" value={p.epochs} onChange={e => p.setEpochs(Math.max(1, Math.min(500, Number(e.target.value))))}/><small>Pasadas completas por el dataset.</small></label></div><div className="info-callout"><CircleHelp size={17}/><span><b>Nota sobre familias:</b> Feedforward se representa con capas densas; RNN, CNN y GAN aparecen como opciones conceptuales en este prototipo. No se construye ni entrena una arquitectura ML real.</span></div></section></> }

function Training(p: { jobs: Job[]; projects: Project[]; selectedProjectId: string; setSelectedProjectId: (v: string) => void; epochs: number; setEpochs: (v: number) => void; start: () => void; updateStatus: (id: string, status: Job['status']) => void; remove: (id: string) => void; exportJobs: () => void; filter: string; setFilter: (v: string) => void }) { const jobs = p.jobs.filter(j => p.filter === 'Todos' || j.status === p.filter); const selected = p.jobs.find(j => j.status === 'En ejecución') || p.jobs[0]; return <><PageIntro eyebrow="EXPERIMENT CONTROL CENTER" title="Entrenamientos" description="Lanza ejecuciones de demostración, sigue la época actual y administra su estado." action={<button className="btn btn-secondary" onClick={p.exportJobs}><Download size={16}/> Exportar CSV</button>}/><div className="training-launch panel"><div className="launch-icon"><Zap size={23}/></div><div className="launch-description"><h3>Configurar nueva ejecución</h3><p>Elige un proyecto con dataset y establece cuántas épocas simular.</p></div><label>Proyecto<select value={p.selectedProjectId} onChange={e => p.setSelectedProjectId(e.target.value)}>{p.projects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Épocas<input type="number" min="1" max="500" value={p.epochs} onChange={e => p.setEpochs(Math.max(1, Math.min(500, Number(e.target.value))))}/></label><button className="btn btn-primary" onClick={p.start} disabled={!p.projects.length}><Play size={16} fill="currentColor"/> Iniciar simulación</button></div><div className="training-stat-grid"><Metric label="En ejecución" value={p.jobs.filter(j => j.status === 'En ejecución').length} note="Actualización automática" icon={Activity} color="green"/><Metric label="Completados" value={p.jobs.filter(j => j.status === 'Completado').length} note="Épocas finalizadas" icon={CheckCircle2} color="purple"/><Metric label="Pausados" value={p.jobs.filter(j => j.status === 'Pausado').length} note="Se pueden reanudar" icon={Pause} color="orange"/><Metric label="Total ejecuciones" value={p.jobs.length} note="Historial local" icon={Gauge} color="blue"/></div>{selected && <section className="panel active-run-panel"><div className="panel-heading"><div><span className="eyebrow">LIVE RUN MONITOR</span><h3>{selected.projectName}</h3><p>{selected.id} · {selected.family} · {selected.optimizer} · {selected.lossFunction}</p></div><Status value={selected.status}/></div><div className="run-progress-top"><div><span>Época actual</span><b>{selected.epoch} <small>/ {selected.epochs}</small></b></div><div><span>Tiempo transcurrido</span><b>{selected.elapsed}s</b></div><div><span>Pérdida actual</span><b>{selected.loss.toFixed(4)}</b></div><div><span>Precisión simulada</span><b>{(selected.accuracy * 100).toFixed(2)}%</b></div></div><div className="progress-track"><span style={{ width: `${Math.round(selected.epoch / selected.epochs * 100)}%` }}/></div><div className="run-panel-footer"><span>{selected.status === 'Completado' ? <CheckCircle2 size={15}/> : <Activity size={15}/>} {selected.status === 'Completado' ? 'Simulación finalizada' : selected.status === 'En ejecución' ? 'Las métricas se actualizan cada segundo' : `Estado: ${selected.status}`}</span><div>{selected.status === 'En ejecución' && <button className="btn btn-secondary btn-small" onClick={() => p.updateStatus(selected.id, 'Pausado')}><Pause size={14}/> Pausar</button>}{selected.status === 'Pausado' && <button className="btn btn-secondary btn-small" onClick={() => p.updateStatus(selected.id, 'En ejecución')}><Play size={14}/> Reanudar</button>}{['En ejecución','Pausado'].includes(selected.status) && <button className="btn btn-danger btn-small" onClick={() => p.updateStatus(selected.id, 'Cancelado')}><X size={14}/> Desactivar</button>}</div></div>{selected.history.length > 1 && <div className="chart-box run-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={selected.history}><CartesianGrid strokeDasharray="4 4" vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="epoch" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--border)', borderRadius: 10 }}/><Area type="monotone" dataKey="loss" name="Pérdida" stroke="#7657f6" fill="#7657f622" strokeWidth={2}/><Area type="monotone" dataKey="accuracy" name="Precisión" stroke="#13b98b" fill="#13b98b18" strokeWidth={2}/></AreaChart></ResponsiveContainer></div>}</section>}<section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">RUN HISTORY</span><h3>Historial de ejecuciones</h3><p>Pausa, reactiva, desactiva, elimina o exporta el historial.</p></div><select className="filter-select" value={p.filter} onChange={e => p.setFilter(e.target.value)}>{['Todos','En ejecución','Completado','Pausado','Cancelado','Incompleto'].map(s => <option key={s}>{s}</option>)}</select></div>{jobs.length ? <div className="table-scroll"><table><thead><tr><th>Ejecución / Proyecto</th><th>Progreso</th><th>Pérdida</th><th>Precisión</th><th>Tiempo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{jobs.map(job => <tr key={job.id}><td><div className="table-primary"><div className="table-project-icon"><Activity size={16}/></div><span><b>{job.projectName}</b><small>{job.id}</small></span></div></td><td>{job.epoch}/{job.epochs} <div className="mini-progress"><i style={{ width: `${job.epoch / job.epochs * 100}%` }}/></div></td><td>{job.loss.toFixed(4)}</td><td>{(job.accuracy * 100).toFixed(2)}%</td><td>{job.elapsed}s</td><td><Status value={job.status}/></td><td><div className="table-actions">{job.status === 'En ejecución' && <button title="Pausar" onClick={() => p.updateStatus(job.id, 'Pausado')}><Pause size={15}/></button>}{job.status === 'Pausado' && <button title="Reanudar" onClick={() => p.updateStatus(job.id, 'En ejecución')}><Play size={15}/></button>}{['En ejecución','Pausado'].includes(job.status) && <button title="Desactivar" onClick={() => p.updateStatus(job.id, 'Cancelado')}><X size={15}/></button>}<button title="Eliminar" className="danger-text" onClick={() => p.remove(job.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div> : <Empty icon={Activity} title="No hay entrenamientos" text="Selecciona un proyecto y pulsa Iniciar simulación para generar métricas."/>}</section></> }

function Models(p: { jobs: Job[]; projects: Project[]; go: (k: ModuleKey) => void; toggleModel: (id: string) => void }) { const completed = p.jobs.filter(j => j.status === 'Completado'); return <><PageIntro eyebrow="MODEL REGISTRY" title="Modelos creados" description="Consulta modelos simulados a partir de entrenamientos y controla si siguen activos en el workspace." action={<button className="btn btn-secondary" onClick={() => p.go('training')}><Zap size={16}/> Ver entrenamientos</button>}/><div className="metric-grid"><Metric label="Modelos registrados" value={completed.length} note="Entrenamientos completados" icon={BrainCircuit} color="purple"/><Metric label="Modelos activos" value={completed.filter(j => j.modelActive).length} note="Disponibles en la demo" icon={CheckCircle2} color="green"/><Metric label="Familias usadas" value={new Set(p.jobs.map(j => j.family)).size} note="De 4 familias posibles" icon={Network} color="blue"/><Metric label="Proyectos con modelo" value={new Set(completed.map(j => j.projectId)).size} note="Con ejecución completada" icon={FolderKanban} color="orange"/></div><section className="panel table-panel"><div className="panel-heading"><div><h3>Registro de versiones</h3><p>Un registro se genera cuando una simulación completa todas sus épocas.</p></div></div>{completed.length ? <div className="model-card-grid">{completed.map((job, i) => <article className="model-card" key={job.id}><div className="model-card-top"><div className="model-symbol"><BrainCircuit size={22}/></div><span className="model-version">v1.{i.toString().padStart(2,'0')}</span><Status value={job.modelActive ? 'Activo' : 'Inactivo'}/><button className="icon-btn" title={job.modelActive ? 'Desactivar modelo' : 'Activar modelo'} onClick={() => p.toggleModel(job.id)}>{job.modelActive ? <Pause size={15}/> : <Play size={15}/>}</button></div><h3>{job.projectName}</h3><p>{job.id} · {job.family}</p><div className="model-metrics"><div><small>Precisión</small><b>{(job.accuracy * 100).toFixed(2)}%</b></div><div><small>Pérdida</small><b>{job.loss.toFixed(4)}</b></div><div><small>Épocas</small><b>{job.epochs}</b></div></div><div className="model-card-footer"><span><CheckCircle2 size={14}/> Simulado</span><button className="inline-action" onClick={() => p.go('evaluation')}>Ver métricas →</button></div></article>)}</div> : <Empty icon={GitBranch} title="Aún no hay modelos completados" text="Completa una simulación de entrenamiento para registrar una versión de modelo." action={<button className="btn btn-primary" onClick={() => p.go('training')}>Ir a entrenamientos</button>}/>}</section></> }

function Evaluation(p: { jobs: Job[] }) { const job = p.jobs.find(j => j.status === 'Completado') || p.jobs[0]; return <><PageIntro eyebrow="MODEL ANALYTICS" title="Evaluación y métricas" description="Analiza pérdida, precisión y duración de las ejecuciones simuladas."/><div className="metric-grid"><Metric label="Ejecuciones totales" value={p.jobs.length} note="En el navegador" icon={Activity} color="purple"/><Metric label="Precisión promedio" value={p.jobs.length ? `${(p.jobs.reduce((n,j) => n + j.accuracy,0) / p.jobs.length * 100).toFixed(2)}%` : '—'} note="Todas las ejecuciones" icon={Gauge} color="green"/><Metric label="Pérdida promedio" value={p.jobs.length ? (p.jobs.reduce((n,j) => n + j.loss,0) / p.jobs.length).toFixed(4) : '—'} note="Valor simulado" icon={BarChart3} color="blue"/><Metric label="Tiempo acumulado" value={`${p.jobs.reduce((n,j) => n + j.elapsed,0)}s`} note="Tiempo de demostración" icon={Clock3} color="orange"/></div>{job ? <section className="panel performance-panel"><div className="panel-heading"><div><span className="eyebrow">SELECTED EXPERIMENT</span><h3>{job.projectName}</h3><p>{job.id} · La curva usa datos generados durante la simulación.</p></div><Status value={job.status}/></div>{job.history.length > 1 ? <div className="chart-box large-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={job.history}><CartesianGrid strokeDasharray="4 4" vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="epoch"/><YAxis/><Tooltip contentStyle={{ background: 'var(--panel)', border: '1px solid var(--border)', borderRadius: 10 }}/><Area type="monotone" dataKey="loss" name="Pérdida" stroke="#7657f6" fill="#7657f622" strokeWidth={2.5}/><Area type="monotone" dataKey="accuracy" name="Precisión" stroke="#13b98b" fill="#13b98b18" strokeWidth={2}/></AreaChart></ResponsiveContainer></div> : <Empty icon={BarChart3} title="Generando datos" text="La curva aparecerá conforme avance la simulación."/>}</section> : <Empty icon={BarChart3} title="No hay métricas registradas" text="Inicia un entrenamiento simulado para generar métricas."/>}</> }

function Reports(p: { projects: Project[]; datasets: Dataset[]; jobs: Job[]; exportJobs: () => void }) { const exportSummary = () => { const lines = ['NEUROLAB ENTERPRISE — INFORME SIMULADO', `Generado: ${new Date().toLocaleString('es-PE')}`, '', 'PROYECTOS', ...p.projects.map(x => `${x.id} | ${x.name} | ${x.family} | ${x.status}`), '', 'DATASETS', ...p.datasets.map(x => `${x.id} | ${x.name} | ${x.rows} filas | ${x.columns} columnas`), '', 'ENTRENAMIENTOS', ...p.jobs.map(x => `${x.id} | ${x.projectName} | ${x.status} | loss=${x.loss} | accuracy=${x.accuracy}`), '', 'Nota: los valores de entrenamiento son simulados.'].join('\n'); const url = URL.createObjectURL(new Blob([lines], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'neurolab_informe.txt'; a.click(); URL.revokeObjectURL(url) }; return <><PageIntro eyebrow="REPORT CENTER" title="Centro de reportes" description="Exporta el estado del workspace, los proyectos, datasets y ejecuciones de entrenamiento." action={<button className="btn btn-primary" onClick={exportSummary}><Download size={16}/> Descargar resumen</button>}/><div className="report-grid">{[{title:'Resumen de proyectos',text:'Nombres, familias neuronales, estado y dataset asociado.',count:p.projects.length,icon:FolderKanban},{title:'Inventario de datasets',text:'Archivos registrados, filas, columnas y tamaño.',count:p.datasets.length,icon:Database},{title:'Historial de entrenamientos',text:'Épocas, precisión, pérdida, tiempo y estado.',count:p.jobs.length,icon:Activity},{title:'Métricas y evaluación',text:'Resumen de las curvas y valores de cada ejecución.',count:p.jobs.filter(j=>j.history.length>0).length,icon:BarChart3}].map(item => <article className="report-card panel" key={item.title}><div className="report-icon"><item.icon size={22}/></div><h3>{item.title}</h3><p>{item.text}</p><div className="report-card-bottom"><span>{item.count} registro(s)</span><button className="inline-action" onClick={item.title.includes('entrenamientos') ? p.exportJobs : exportSummary}>Exportar <Download size={14}/></button></div></article>)}</div><div className="info-callout"><FileText size={18}/><span>Los reportes se generan localmente desde los datos de esta demo. La exportación de entrenamientos está disponible en formato CSV para abrir en Excel.</span></div></> }

function Fundamentals() { return <><PageIntro eyebrow="LEARNING CENTER" title="Fundamentos neuronales" description="Referencia rápida de los elementos que puedes configurar en el diseñador."/><div className="fundamental-grid">{[{n:'01',title:'Capa de entrada',desc:'Recibe las características del dataset. En una red tabular, cada variable puede representar una característica de entrada.',icon:Database,color:'violet'},{n:'02',title:'Capas ocultas',desc:'Transforman la información mediante pesos, sesgos y funciones de activación. Puedes agregar tantas como necesite tu experimento.',icon:Layers3,color:'blue'},{n:'03',title:'Capa de salida',desc:'Produce la salida del modelo. El número de neuronas depende del tipo de problema y de las etiquetas esperadas.',icon:GitBranch,color:'green'},{n:'04',title:'Función de activación',desc:'Introduce no linealidad. Esta demo ofrece Sigmoid, ReLU, Tanh, Softmax y Linear.',icon:Zap,color:'orange'},{n:'05',title:'Optimizador',desc:'Determina cómo se ajustan los parámetros. Adam, SGD y RMSprop son las opciones de la interfaz.',icon:Activity,color:'pink'},{n:'06',title:'Función de pérdida',desc:'Cuantifica el error entre la predicción y el objetivo. Las opciones son binary_crossentropy, categorical_crossentropy y mse.',icon:Gauge,color:'cyan'}].map(item => <article className="fundamental-card panel" key={item.n}><div className={`fundamental-icon ${item.color}`}><item.icon size={22}/></div><span className="fundamental-number">{item.n}</span><h3>{item.title}</h3><p>{item.desc}</p></article>)}</div><section className="panel family-reference"><div className="panel-heading"><div><span className="eyebrow">NETWORK FAMILIES</span><h3>Familias de redes disponibles</h3><p>Las cuatro opciones pueden seleccionarse en el flujo de creación de proyectos.</p></div></div><div className="family-grid">{[{name:'Feedforward',tag:'Datos tabulares',text:'La información fluye desde la entrada hacia la salida.'},{name:'RNN',tag:'Secuencias',text:'Pensada conceptualmente para datos ordenados en el tiempo.'},{name:'CNN',tag:'Imágenes',text:'Pensada conceptualmente para patrones espaciales.'},{name:'GAN',tag:'Generación',text:'Familia generativa basada en dos redes que compiten.'}].map(f => <div className="family-reference-item" key={f.name}><div><Network size={18}/><b>{f.name}</b></div><span>{f.tag}</span><p>{f.text}</p></div>)}</div><div className="info-callout"><AlertTriangle size={17}/><span>La aplicación actual es una simulación visual: no construye ni entrena redes reales Feedforward, RNN, CNN o GAN.</span></div></section></> }

function Admin(p: { user: User; theme: string; reset: () => void }) { return <><PageIntro eyebrow="WORKSPACE SETTINGS" title="Administración" description="Información de la sesión, preferencias de interfaz y controles de la demo."/><div className="admin-profile panel"><div className="admin-profile-avatar"><ShieldCheck size={28}/></div><div className="admin-profile-copy"><span className="eyebrow">CUENTA ACTIVA</span><h3>{p.user.name}</h3><p>{p.user.email} · Rol {p.user.role}</p></div><Status value="Activo"/></div><div className="admin-grid"><section className="panel"><div className="panel-heading"><div><h3>Preferencias</h3><p>Opciones de apariencia y entorno.</p></div><Settings size={19}/></div><div className="admin-setting-row"><div><b>Tema de interfaz</b><small>Actual: {p.theme === 'light' ? 'Claro' : 'Oscuro'}</small></div><span className="subtle-badge">Configurable desde la barra superior</span></div><div className="admin-setting-row"><div><b>Persistencia local</b><small>La demo conserva los datos en localStorage del navegador.</small></div><CheckCircle2 size={18} className="success-icon"/></div><div className="admin-setting-row"><div><b>Motor de entrenamiento</b><small>Simulado; no consume CPU/GPU para entrenar.</small></div><span className="status-pill status-amber"><i/>Demo</span></div></section><section className="panel reset-panel"><div className="reset-icon"><RotateCcw size={22}/></div><h3>Restablecer datos</h3><p>Elimina proyectos, datasets y ejecuciones añadidos en esta sesión y recupera los registros de ejemplo.</p><button className="btn btn-danger" onClick={p.reset}><Trash2 size={16}/> Restablecer demostración</button></section></div><div className="info-callout"><ShieldCheck size={18}/><span>Esta versión está pensada para exposición académica. Antes de publicar en internet, reemplaza el acceso de demostración por autenticación segura y una API real con autorización y persistencia.</span></div></> }
